import{_ as l,b as e,e as n,a7 as i}from"./chunks/framework.BCCJKnGb.js";const u=JSON.parse('{"title":"3 分钟接入","description":"把国新学伴接进个人 Agent 的最短步骤。","frontmatter":{"title":"3 分钟接入","description":"把国新学伴接进个人 Agent 的最短步骤。","type":"agent-quickstart","tags":["Agent","快速开始"],"updated":"2026-11-06T00:00:00.000Z"},"headers":[],"relativePath":"agent/quickstart.md","filePath":"agent/quickstart.md","lastUpdated":null}'),t={name:"agent/quickstart.md"};function s(o,a,p,d,c,r){return e(),n("div",null,[...a[0]||(a[0]=[i(`<h1 id="_3-分钟接入" tabindex="-1">3 分钟接入 <a class="header-anchor" href="#_3-分钟接入" aria-label="Permalink to &quot;3 分钟接入&quot;">​</a></h1><h2 id="路线-a-复制提示词-最常见" tabindex="-1">路线 A：复制提示词（最常见） <a class="header-anchor" href="#路线-a-复制提示词-最常见" aria-label="Permalink to &quot;路线 A：复制提示词（最常见）&quot;">​</a></h2><p>适合：ChatGPT、Claude、豆包、Kimi、元宝等能联网/能打开链接的 Agent。</p><ol><li>打开你的 Agent。</li><li>复制下面的提示词。</li><li>把域名换成你的站点域名。</li><li>问一句：“2024 级国新系培养方案有哪些学分模块？”</li><li>看它有没有附上页面链接；没有链接就要求它“先读 index.json，再回答”。</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你是我的“国新学伴”学习助手。请先读取这个索引：</span></span>
<span class="line"><span>https://guoxin.wxr535.cn/agent/index.json</span></span>
<span class="line"><span></span></span>
<span class="line"><span>工作规则：</span></span>
<span class="line"><span>1. 先读索引，再决定读哪个页面；不要凭记忆回答。</span></span>
<span class="line"><span>2. 回答时附上你读过的页面链接。</span></span>
<span class="line"><span>3. 如果索引/页面打不开，直接说“打不开”，不要编造。</span></span>
<span class="line"><span>4. 涉及培养方案、推免资格等关键政策，提醒我以学院/教务最新通知为准。</span></span>
<span class="line"><span>5. 不要输出任何个人隐私信息。</span></span></code></pre></div><h2 id="路线-b-上传内容包-不能联网时" tabindex="-1">路线 B：上传内容包（不能联网时） <a class="header-anchor" href="#路线-b-上传内容包-不能联网时" aria-label="Permalink to &quot;路线 B：上传内容包（不能联网时）&quot;">​</a></h2><p>适合：只能上传文件/知识库的 Agent。</p><ol><li>打开 <a href="/agent/content.md" download>内容包 content.md</a>（或右键另存为）。</li><li>上传到 Agent 的知识库/文件区。</li><li>用上面的提示词，但把“请先读取索引”改成“请先读我上传的 content.md”。</li><li>问问题时要求它“引用标题 + 链接”。</li></ol><div class="tip custom-block"><p class="custom-block-title">内容包是什么</p><p><code>content.md</code> 是整站正文的合并版，方便不能联网的 Agent 一次性读取。它可能不是最新；重要信息以页面为准。</p></div><h2 id="路线-c-安装-skill-包" tabindex="-1">路线 C：安装 Skill 包 <a class="header-anchor" href="#路线-c-安装-skill-包" aria-label="Permalink to &quot;路线 C：安装 Skill 包&quot;">​</a></h2><p>适合：支持 Skill/插件的客户端（如 Claude Code、DSH、Codex 等）。</p><ol><li>下载 <a href="/mingxin-demo/downloads/ruc-jc-study.zip">Skill 包</a>。</li><li>解压到客户端的 skills 目录，或在客户端里选择“安装本地 Skill”。</li><li>确认它读取的是 <code>https://guoxin.wxr535.cn/agent/index.json</code>。</li><li>问一句测试问题，检查是否引用来源。</li></ol><p>详细说明见 <a href="/mingxin-demo/agent/skill">Skill 包</a>。</p><h2 id="接入自检清单" tabindex="-1">接入自检清单 <a class="header-anchor" href="#接入自检清单" aria-label="Permalink to &quot;接入自检清单&quot;">​</a></h2><ul><li>[ ] 能打开 <code>index.json</code></li><li>[ ] 回答里带页面链接</li><li>[ ] 不知道时会说“没有找到”，而不是编造</li><li>[ ] 没有输出个人隐私</li><li>[ ] 关键政策会提醒“以官方为准”</li></ul><h2 id="打不开怎么办" tabindex="-1">打不开怎么办 <a class="header-anchor" href="#打不开怎么办" aria-label="Permalink to &quot;打不开怎么办&quot;">​</a></h2><ol><li>换网络：校园 Wi-Fi / 手机 4G 各试一次。</li><li>把 <code>https://</code> 换成 <code>http://</code> 试一次（有些代理会拦截）。</li><li>让 Agent 直接读 <code>content.md</code>，不要读网页。</li><li>还不行：在班级群反馈，或让站长发你一份离线包。</li></ol>`,17)])])}const g=l(t,[["render",s]]);export{u as __pageData,g as default};
